import java.util.HashMap;
import java.util.Map;

public class Logger {

    private Map<String, Integer> lastPrintTimestamps = new HashMap<>();

    public boolean shouldPrintMessage(int timestamp, String message) {
        Integer last = lastPrintTimestamps.get(message);
        if (last == null || timestamp - last >= 10) {
            lastPrintTimestamps.put(message, timestamp);
            return true;
        }
        return false;
    }
}

